	}

	vm.builtins["tonumber"] = func(args ...interface{}) (interface{}, error) {
		if len(args) == 0 {
			return 0.0, nil
		}
		switch v := args[0].(type) {
		case float64:
			return v, nil
		case int64:
			return float64(v), nil
		case string:
