func TestRecordCollectionTime(t *testing.T) {
	gc := NewGC()
	optimizer := NewGCOptimizer(gc)

	duration := 5 * time.Millisecond

	optimizer.RecordCollectionTime(duration)

	stats := optimizer.GetStatistics()
	if stats.TotalPauseTime != duration {
