	pool := NewMemoryPool()

	for i := 0; i < 10; i++ {
		pool.Allocate(8)
	}

	optimizer := NewGCOptimizer(nil)

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		optimizer.OptimizePoolSizing(pool)
	}
}

