func BenchmarkGCOptimization(b *testing.B) {
	gc := NewGC()
	optimizer := NewGCOptimizer(gc)

	for i := 0; i < 100; i++ {
		gc.Allocate(i, 8, "number")
	}

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		optimizer.OptimizeCollectionTiming()
		optimizer.ReduceFragmentation()
		optimizer.OptimizeRootTracking()
	}
}

